public class OrderService
{
    private readonly AppDbContext _db;

    public async Task PlaceOrderAsync(PlaceOrderCommand cmd)
    {
        var order = new Order { /* ... */ };
        var outbox = new OutboxMessage
        {
            Id = Guid.NewGuid(),
            Topic = "orders.created",
            Payload = JsonSerializer.Serialize(order),
            CreatedAt = DateTime.UtcNow
        };

        await using var tx = await _db.Database.BeginTransactionAsync();
        try
        {
            await _db.Orders.AddAsync(order);
            await _db.OutboxMessages.AddAsync(outbox);
            await _db.SaveChangesAsync();
            await tx.CommitAsync();
        }
        catch
        {
            await tx.RollbackAsync();
            throw;
        }
    }
}

const { Kafka } = require('kafkajs');
const { Pool } = require('pg');

const kafka = new Kafka({ brokers: ['localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'order-processors' });
const db = new Pool({ connectionString: process.env.DATABASE_URL });

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'orders.created', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ message }) => {
      const client = await db.connect();
      try {
        await client.query('BEGIN');

        const order = JSON.parse(message.value);
        await client.query(
          'INSERT INTO processed_orders (id, data) VALUES ($1, $2)',
          [order.id, JSON.stringify(order)]
        );

        await client.query('COMMIT');
        await consumer.commitOffsets([{ topic: 'orders.created', partition: message.partition, offset: message.offset }]);
      } catch (err) {
        await client.query('ROLLBACK');
        console.error('Processing failed, message will be redelivered:', err);
      } finally {
        client.release();
      }
    }
  });
}

run();
